import crypto from "node:crypto";

const TOKEN_BYTE_LENGTH = 32;

export const generateTokenHash = (token: string) =>
  crypto.createHash("sha256").update(token).digest("hex");

export const generateToken = () => {
  const token = crypto.randomBytes(TOKEN_BYTE_LENGTH).toString("hex");
  const hash = generateTokenHash(token);
  return { hash, token };
};
/**
 * Where the confirmation link points. The request's own origin is what a
 * preview deployment or a local run needs — the token is in that database
 * — but it comes from the Host header, which anything can send. So the
 * request origin is honoured only when its host is the configured site,
 * one of this deployment's own hostnames (VERCEL_URL and VERCEL_BRANCH_URL,
 * set by the platform), or localhost. Any other host, including someone
 * else's *.vercel.app, gets the configured origin.
 */
export function confirmationOrigin(
  requestUrl: string,
  configuredUrl: string,
  deploymentHosts: readonly (string | undefined)[] = [
    process.env.VERCEL_URL,
    process.env.VERCEL_BRANCH_URL,
  ]
): string {
  const configured = new URL(configuredUrl).origin;
  let request: URL;
  try {
    request = new URL(requestUrl);
  } catch {
    return configured;
  }

  const host = request.hostname;
  const trusted =
    request.origin === configured ||
    host === "localhost" ||
    host === "127.0.0.1" ||
    deploymentHosts.some((own) => own && own.toLowerCase() === host);

  return trusted ? request.origin : configured;
}
import { keys as rateLimitKeys } from "@repo/rate-limit/keys";

/**
 * A sliding-window limiter for the two forms that send mail.
 *
 * Production has no Upstash keys today, so the Redis limiter in
 * `@repo/rate-limit` would be a no-op there. This one runs in memory when
 * Redis is absent: per function instance, reset on cold start, so it bounds
 * a burst rather than a patient attacker. That is still the difference
 * between a script sending a confirmation mail per request and one sending a
 * handful per instance per window. A platform-level rule (Vercel WAF rate
 * limiting) is the stronger tool and needs no code; this is the floor under
 * it. When Upstash is configured the same calls share a window across
 * instances.
 */
export interface RateLimitResult {
  readonly success: boolean;
}

export interface RateLimiter {
  readonly limit: (key: string) => Promise<RateLimitResult>;
}

export interface Window {
  readonly limit: number;
  readonly ms: number;
}

const MAX_TRACKED_KEYS = 10_000;

export function createMemoryLimiter(
  window: Window,
  now: () => number = Date.now
): RateLimiter {
  const hits = new Map<string, number[]>();

  const prune = (stamps: number[], cutoff: number) => {
    let i = 0;
    while (i < stamps.length && (stamps[i] as number) <= cutoff) {
      i += 1;
    }
    return i === 0 ? stamps : stamps.slice(i);
  };

  return {
    limit(key) {
      const current = now();
      const cutoff = current - window.ms;
      const recent = prune(hits.get(key) ?? [], cutoff);

      if (recent.length >= window.limit) {
        hits.set(key, recent);
        return Promise.resolve({ success: false });
      }

      if (hits.size >= MAX_TRACKED_KEYS && !hits.has(key)) {
        // Drop the oldest tracked key rather than grow without bound.
        const oldest = hits.keys().next().value;
        if (oldest !== undefined) {
          hits.delete(oldest);
        }
      }

      recent.push(current);
      hits.set(key, recent);
      return Promise.resolve({ success: true });
    },
  };
}

async function createRedisLimiter(
  window: Window,
  prefix: string
): Promise<RateLimiter> {
  const { createRateLimiter, slidingWindow } = await import("@repo/rate-limit");
  const seconds = Math.max(1, Math.round(window.ms / 1000));
  const limiter = createRateLimiter({
    limiter: slidingWindow(window.limit, `${seconds} s`),
    prefix: `has-toggle:${prefix}`,
  });
  return {
    async limit(key) {
      const { success } = await limiter.limit(key);
      return { success };
    },
  };
}

const redisConfigured = () => {
  const env = rateLimitKeys();
  return Boolean(env.UPSTASH_REDIS_REST_URL && env.UPSTASH_REDIS_REST_TOKEN);
};

/**
 * One limiter per (prefix, window), created on first use. The memory
 * variant lives for the instance; the Redis variant is stateless here.
 */
const limiters = new Map<string, Promise<RateLimiter>>();

/** Forgets every window. For tests that share a process. */
export function resetRateLimiters(): void {
  limiters.clear();
}

export function rateLimiter(
  prefix: string,
  window: Window
): Promise<RateLimiter> {
  const id = `${prefix}:${window.limit}:${window.ms}`;
  let limiter = limiters.get(id);
  if (!limiter) {
    limiter = redisConfigured()
      ? createRedisLimiter(window, prefix)
      : Promise.resolve(createMemoryLimiter(window));
    limiters.set(id, limiter);
  }
  return limiter;
}

/**
 * The caller's address as Vercel reports it. `x-real-ip` is set by the
 * platform; the leftmost `x-forwarded-for` entry is the fallback. Neither
 * present means no per-IP key at all — better no limit than one bucket
 * shared by everyone behind a missing header.
 */
export function clientIp(headers: Headers): string | null {
  const real = headers.get("x-real-ip")?.trim();
  if (real) {
    return real;
  }
  const forwarded = headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  return forwarded || null;
}
import { isToolbarEnabled } from "@repo/feature-flags/lib/toolbar-enabled";
import { internationalizationMiddleware } from "@repo/internationalization/middleware";
import { parseError } from "@repo/observability/error";
import { secure } from "@repo/security";
import { createNEMO } from "@zanreal/nemo";
import {
  type NextFetchEvent,
  type NextProxy,
  type NextRequest,
  NextResponse,
} from "next/server";
import { env } from "@/env";
import {
  securityHeaders,
  securityOptions,
  securityOptionsWithToolbar,
  withSecurityHeaders,
} from "@/lib/security-headers";

export const config = {
  matcher: [
    // Skip Next.js internals and all static files, unless found in search params
    "/((?!_next|ingest|monitoring|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
    // Always run for API routes
    "/(api|trpc)(.*)",
  ],
};

// Only widen the CSP where the toolbar actually renders. Keying this on
// FLAGS_SECRET alone meant production carried vercel.live allowances for a
// toolbar it no longer loads.
const headerOptions = isToolbarEnabled()
  ? securityOptionsWithToolbar
  : securityOptions;

// Custom middleware for Arcjet security checks
const arcjetMiddleware = async (request: NextRequest) => {
  if (!env.ARCJET_KEY) {
    return;
  }

  try {
    await secure(
      [
        // See https://docs.arcjet.com/bot-protection/identifying-bots
        "CATEGORY:SEARCH_ENGINE", // Allow search engines
        "CATEGORY:PREVIEW", // Allow preview links to show OG images
        "CATEGORY:MONITOR", // Allow uptime monitoring services
      ],
      request
    );
  } catch (error) {
    // The reason goes to Sentry; the visitor gets the same line either way.
    parseError(error);
    return NextResponse.json({ error: "Access denied" }, { status: 403 });
  }
};

// Skip i18n rewriting for routes outside [locale] (i18n middleware's own
// matcher excludes these, but proxy.ts runs it for all matched routes via
// createNEMO, causing rewrites to /en/... paths that don't exist). The two
// metadata files live at the app root, where Next serves them from.
const UNLOCALIZED = new Set(["/robots.txt", "/sitemap.xml"]);

const i18nWithExclusions = (request: NextRequest) => {
  const { pathname } = request.nextUrl;
  if (
    UNLOCALIZED.has(pathname) ||
    pathname.startsWith("/api") ||
    pathname.startsWith("/confirmed") ||
    pathname.startsWith("/.well-known")
  ) {
    return;
  }
  return internationalizationMiddleware(request);
};

// Compose the app's own middleware (i18n + arcjet) with Nemo
const composedMiddleware = createNEMO(
  {},
  {
    // biome-ignore lint/suspicious/noExplicitAny: Type cast needed due to Next.js type duplication in monorepo
    before: [i18nWithExclusions as any, arcjetMiddleware],
  }
);

// The chain always answers with a response of its own — a locale rewrite, a
// redirect, an Arcjet refusal, or NEMO's plain `next()` — so the security
// headers are merged onto whatever comes back rather than offered as a
// fallback that never gets used.
export const proxy: NextProxy = async (
  request: NextRequest,
  event: NextFetchEvent
) => {
  const response =
    (await composedMiddleware(request, event)) ?? NextResponse.next();
  return withSecurityHeaders(response, securityHeaders(headerOptions));
};

import { createId, database, type Subscriber } from "@repo/database";
import { resend } from "@repo/email";
import AlreadySubscribed from "@repo/email/templates/already-subscribed";
import ConfirmSubscription from "@repo/email/templates/confirm-subscription";
import { parseError } from "@repo/observability/error";
import { log } from "@repo/observability/log";
import { type NextRequest, NextResponse } from "next/server";
import { env } from "@/env";
import { confirmationOrigin } from "@/lib/confirmation-origin";
import {
  EMAIL_COLLATION,
  normalizeEmail,
  type ValidationFailureReason,
  validateEmail,
} from "@/lib/email-validation";
import { clientIp, rateLimiter } from "@/lib/rate-limit";
import { generateToken } from "@/lib/token";

const TOKEN_EXPIRY_MS = 1000 * 60 * 60 * 24;

// A resubmit inside this window sends nothing: it is a double click or
// someone hammering an address that is not theirs. After it, a resubmit
// means "the first mail never arrived" and a fresh one goes out.
const RESEND_COOLDOWN_MS = 1000 * 60 * 2;

// Every request past the format check costs a deliverability lookup, a
// database write and a mail, so callers are capped before that point: a
// burst per address, and a burst per caller across addresses. A real person
// retrying a typo fits inside both.
const PER_ADDRESS = { limit: 3, ms: 1000 * 60 * 60 };
const PER_CALLER = { limit: 10, ms: 1000 * 60 * 10 };

const LIMIT_MESSAGE =
  "That’s a lot of attempts in a short time. Try again in a little while.";

// Vague messaging for disposable/undeliverable to avoid revealing rejection reason
const VALIDATION_MESSAGES: Record<ValidationFailureReason, string> = {
  disposable:
    "This email address doesn't look quite right. Mind trying another one?",
  invalid_format: "Invalid email address provided",
  undeliverable:
    "This email address doesn't look quite right. Mind trying another one?",
};

// The same reply for every outcome, so the form cannot be used to test
// whether an address is on the list. What differs is the mail that arrives.
const SUCCESS_MESSAGE = "Check your inbox. One click confirms it.";

const EMAIL_SHAPE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const DUPLICATE_KEY = 11_000;

function isDuplicateKey(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    error.code === DUPLICATE_KEY
  );
}

// Issue time is not stored; the expiry is, and the lifetime is fixed.
function tokenIssuedAt(subscriber: Subscriber): number {
  return subscriber.tokenExpiresAt
    ? subscriber.tokenExpiresAt.getTime() - TOKEN_EXPIRY_MS
    : Number.NEGATIVE_INFINITY;
}

async function overLimit(request: NextRequest, email: string) {
  const [byAddress, byCaller] = await Promise.all([
    rateLimiter("confirm:address", PER_ADDRESS),
    rateLimiter("confirm:caller", PER_CALLER),
  ]);
  const ip = clientIp(request.headers);
  const [address, caller] = await Promise.all([
    byAddress.limit(email),
    ip ? byCaller.limit(ip) : Promise.resolve({ success: true }),
  ]);
  return !(address.success && caller.success);
}

function emailError() {
  return NextResponse.json(
    {
      error: {
        message: "Failed to send confirmation email",
        name: "EmailError",
      },
    },
    { status: 500 }
  );
}

/**
 * Writes the token onto the subscriber's row, creating it if there is none.
 * The address arrives normalized, so the plain upsert matches every row
 * written since normalization began. A row stored in another casing before
 * that is invisible to the plain lookup, and the attempted insert trips the
 * case-insensitive unique index (E11000). That is the signal to look again
 * with the index's collation, which finds the legacy row and updates it in
 * place. A retry that matches nothing means the token would be mailed for a
 * row nobody holds, so it is an error rather than a silent success.
 */
async function storeConfirmationToken(email: string, hash: string) {
  const update = {
    $set: {
      token: hash,
      tokenExpiresAt: new Date(Date.now() + TOKEN_EXPIRY_MS),
    },
  };

  try {
    await database.subscriber.updateOne(
      { email },
      {
        ...update,
        $setOnInsert: {
          _id: createId(),
          createdAt: new Date(),
          emailVerified: null,
          image: null,
          name: null,
          role: "user",
        },
      },
      { upsert: true }
    );
  } catch (error) {
    if (!isDuplicateKey(error)) {
      throw error;
    }
    const retry = await database.subscriber.updateOne({ email }, update, {
      collation: EMAIL_COLLATION,
    });
    if (retry.matchedCount === 0) {
      throw new Error(
        "Duplicate key on upsert, but no row matched the address under the index collation",
        { cause: error }
      );
    }
  }
}

async function sendConfirmation(email: string, origin: string) {
  const { token, hash } = generateToken();

  await storeConfirmationToken(email, hash);

  const { error } = await resend.emails.send(
    {
      from: env.RESEND_FROM,
      react: ConfirmSubscription({ baseUrl: origin, token }),
      subject: "One click and you’re on the waitlist",
      to: [email],
    },
    // A retried request with the same token must not send twice.
    { idempotencyKey: `confirm-email/${hash}` }
  );

  return error;
}

async function sendAlreadySubscribed(
  subscriber: Subscriber,
  confirmedAt: Date
) {
  // Contact creation at confirm time swallows its error, so a confirmed
  // subscriber can be missing from the segment. Re-creating is idempotent.
  const [contact, mail] = await Promise.all([
    resend.contacts.create({
      email: subscriber.email,
      segments: [{ id: env.RESEND_SEGMENT_ID }],
      unsubscribed: false,
    }),
    resend.emails.send(
      {
        from: env.RESEND_FROM,
        react: AlreadySubscribed({ confirmedAt }),
        subject: "You’re already on the waitlist",
        to: [subscriber.email],
      },
      // One reminder per address per day, however often the form is sent.
      {
        idempotencyKey: `already-subscribed/${subscriber._id}/${new Date().toISOString().slice(0, 10)}`,
      }
    ),
  ]);

  if (contact.error) {
    parseError(contact.error);
  }

  return mail.error;
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const email = normalizeEmail(body?.email);

    // Junk fails the format check inside validateEmail without touching a
    // window; anything shaped like an address is counted before the costly
    // checks run.
    if (EMAIL_SHAPE.test(email) && (await overLimit(request, email))) {
      return NextResponse.json(
        { error: { message: LIMIT_MESSAGE, name: "RateLimitError" } },
        { status: 429 }
      );
    }

    const validation = await validateEmail(email);

    if (!validation.valid) {
      return NextResponse.json(
        {
          error: {
            message: VALIDATION_MESSAGES[validation.reason],
            name: "ValidationError",
          },
        },
        { status: 400 }
      );
    }

    // Collation-aware, so a row stored in another casing still counts as
    // the same person here and gets the reminder rather than a new token.
    const existing = await database.subscriber.findOne(
      { email },
      { collation: EMAIL_COLLATION }
    );

    if (existing?.emailVerified) {
      const error = await sendAlreadySubscribed(
        existing,
        existing.emailVerified
      );
      if (error) {
        log.error(`Failed to send reminder email: ${JSON.stringify(error)}`);
        return emailError();
      }
      return NextResponse.json({ message: SUCCESS_MESSAGE });
    }

    if (existing && Date.now() - tokenIssuedAt(existing) < RESEND_COOLDOWN_MS) {
      return NextResponse.json({ message: SUCCESS_MESSAGE });
    }

    const error = await sendConfirmation(
      email,
      confirmationOrigin(request.url, env.NEXT_PUBLIC_WEB_URL)
    );
    if (error) {
      log.error(`Failed to send confirmation email: ${JSON.stringify(error)}`);
      return emailError();
    }

    return NextResponse.json({ message: SUCCESS_MESSAGE });
  } catch (error) {
    if (error instanceof SyntaxError) {
      return NextResponse.json(
        {
          error: { message: "Invalid request body", name: "ValidationError" },
        },
        { status: 400 }
      );
    }
    parseError(error);
    return NextResponse.json(
      {
        error: { message: "An unexpected error occurred", name: "ServerError" },
      },
      { status: 500 }
    );
  }
}
import { timingSafeEqual } from "node:crypto";
import { database } from "@repo/database";
import { resend } from "@repo/email";
import { parseError } from "@repo/observability/error";
import { after, type NextRequest, NextResponse } from "next/server";
import { env } from "@/env";
import { removeSubscriber } from "@/lib/subscribers";

/**
 * The safety net under the webhook. Called on a schedule (an Atlas trigger),
 * it makes the two stores agree with the privacy policy again:
 *
 * - a contact Resend has flagged `unsubscribed` is deleted from both stores;
 * - a confirmed subscriber Resend no longer knows (deleted in the dashboard,
 *   webhook missed) is deleted here too;
 * - a signup that never confirmed is dropped once its link has been dead
 *   for a week — the address was collected for a confirmation that never
 *   came, so the purpose it was collected for has ended.
 */
const UNCONFIRMED_GRACE_MS = 1000 * 60 * 60 * 24 * 7;
const PAGE_SIZE = 100;

/**
 * "Orphaned" means Resend no longer knows the address — but an empty or
 * truncated listing looks the same as a deliberate deletion. A wrong segment
 * id, an API that answers with no data and no error, or a partial page would
 * read as "everyone left" and empty the list. So a run that would orphan
 * more than this share of the confirmed subscribers is refused and reported,
 * and a listing that comes back empty while subscribers exist is never
 * trusted. Small lists get an absolute allowance so the first few departures
 * are still processed.
 */
const MAX_ORPHAN_SHARE = 0.5;
const MIN_ORPHAN_ALLOWANCE = 5;

export function orphansLookWrong(
  confirmed: number,
  known: number,
  orphaned: number
): boolean {
  if (confirmed === 0) {
    return false;
  }
  if (known === 0) {
    return true;
  }
  const allowance = Math.max(
    MIN_ORPHAN_ALLOWANCE,
    Math.floor(confirmed * MAX_ORPHAN_SHARE)
  );
  return orphaned > allowance;
}

function authorized(request: NextRequest): boolean {
  const header = request.headers.get("authorization") ?? "";
  const presented = Buffer.from(header);
  const expected = Buffer.from(`Bearer ${env.RECONCILE_SECRET}`);
  return (
    presented.length === expected.length && timingSafeEqual(presented, expected)
  );
}

interface SegmentContact {
  email: string;
  id: string;
  unsubscribed: boolean;
}

// Cursor pagination is sequential by nature: each page's cursor is the
// last id of the page before it.
async function listSegmentContacts(
  cursor?: string,
  collected: SegmentContact[] = []
): Promise<SegmentContact[]> {
  const { data, error } = await resend.contacts.list({
    after: cursor,
    limit: PAGE_SIZE,
    segmentId: env.RESEND_SEGMENT_ID,
  });
  if (error) {
    throw new Error(`Listing contacts failed: ${error.message}`);
  }
  const contacts = [...collected, ...data.data];
  const last = data.data.at(-1);
  if (!(data.has_more && last)) {
    return contacts;
  }
  return listSegmentContacts(last.id, contacts);
}

export async function POST(request: NextRequest) {
  if (!authorized(request)) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const contacts = await listSegmentContacts();
    const known = new Set(contacts.map((c) => c.email));
    const flagged = contacts.filter((c) => c.unsubscribed).map((c) => c.email);

    const confirmed = await database.subscriber
      .find({ emailVerified: { $ne: null } }, { projection: { email: 1 } })
      .toArray();
    const orphaned = confirmed
      .map((s) => s.email)
      .filter((email) => !known.has(email));

    if (orphansLookWrong(confirmed.length, known.size, orphaned.length)) {
      parseError(
        new Error(
          `Reconciliation refused: ${orphaned.length} of ${confirmed.length} confirmed subscribers are missing from ${known.size} listed contacts`
        )
      );
      return NextResponse.json(
        { error: "Reconciliation refused: contact listing looks incomplete" },
        { status: 409 }
      );
    }

    const leaving = [...new Set([...flagged, ...orphaned])];
    await Promise.all(leaving.map(removeSubscriber));

    const { deletedCount: unconfirmed } = await database.subscriber.deleteMany({
      emailVerified: null,
      tokenExpiresAt: { $lt: new Date(Date.now() - UNCONFIRMED_GRACE_MS) },
    });

    return NextResponse.json({
      contacts: contacts.length,
      removed: {
        orphaned: orphaned.length,
        unconfirmed,
        unsubscribed: flagged.length,
      },
    });
  } catch (error) {
    after(() => parseError(error));
    return NextResponse.json(
      { error: "Reconciliation failed" },
      { status: 500 }
    );
  }
}
import { resend, type WebhookEventPayload } from "@repo/email";
import { keys } from "@repo/email/keys";
import { parseError } from "@repo/observability/error";
import { after, type NextRequest, NextResponse } from "next/server";
import { removeSubscriber } from "@/lib/subscribers";

/**
 * Resend reports list exits here. Broadcasts carry Resend's own unsubscribe
 * link, which marks the contact `unsubscribed` rather than deleting it —
 * this route turns that flag into the deletion the privacy policy promises.
 * Hard bounces and spam complaints leave the list the same way: Resend
 * suppresses them on its side, and the address must not linger on ours.
 *
 * Resend retries undelivered webhooks for about a day; the reconciliation
 * endpoint covers anything that slips past that.
 */
function emailsLeaving(event: WebhookEventPayload): string[] {
  switch (event.type) {
    case "contact.updated":
      return event.data.unsubscribed ? [event.data.email] : [];
    case "contact.deleted":
      return [event.data.email];
    case "email.bounced":
      return event.data.bounce.type === "Permanent" ? event.data.to : [];
    case "email.complained":
      return event.data.to;
    default:
      return [];
  }
}

export async function POST(request: NextRequest) {
  const payload = await request.text();

  let event: WebhookEventPayload;
  try {
    event = resend.webhooks.verify({
      headers: {
        id: request.headers.get("svix-id") ?? "",
        signature: request.headers.get("svix-signature") ?? "",
        timestamp: request.headers.get("svix-timestamp") ?? "",
      },
      payload,
      webhookSecret: keys().RESEND_WEBHOOK_SECRET,
    });
  } catch {
    return NextResponse.json({ error: "Invalid signature" }, { status: 400 });
  }

  try {
    await Promise.all(emailsLeaving(event).map(removeSubscriber));
  } catch (error) {
    // A 500 makes Resend retry, which is what a failed deletion needs.
    after(() => parseError(error));
    return NextResponse.json({ error: "Removal failed" }, { status: 500 });
  }

  return NextResponse.json({ received: true });
}

"use server";

import { resend } from "@repo/email";
import ContactTemplate from "@repo/email/templates/contact";
import { parseError } from "@repo/observability/error";
import { headers } from "next/headers";
import { env } from "@/env";
import { clientIp, rateLimiter } from "@/lib/rate-limit";
import { parseContact } from "./schema";

interface ContactState {
  error?: string;
  success?: boolean;
}

// A person writes once, maybe twice with a correction. Three an hour per
// caller leaves room for that and not for a loop.
const PER_CALLER = { limit: 3, ms: 1000 * 60 * 60 };

const MESSAGES = {
  invalid: "Check the three fields: a name, an address that works, a message.",
  limited:
    "That inbox has heard from you a few times already. Try again in an hour.",
  sendFailed:
    "The message didn’t go out. Try again, or write to the address in the footer.",
};

export const contact = async (
  _prevState: ContactState,
  formData: FormData
): Promise<ContactState> => {
  const input = parseContact(formData);
  if (!input) {
    return { error: MESSAGES.invalid };
  }

  try {
    const ip = clientIp(await headers());
    if (ip) {
      const limiter = await rateLimiter("contact", PER_CALLER);
      const { success } = await limiter.limit(ip);
      if (!success) {
        return { error: MESSAGES.limited };
      }
    }

    const { error } = await resend.emails.send({
      from: env.RESEND_FROM,
